1	import { describe, it, expect } from "vitest";
2	import { spawnSync } from "node:child_process";
3	import { runScenario } from "./claim-office.js";
4	
5	const runCliRaw = (scenario: unknown) =>
6	  spawnSync("npx", ["tsx", "src/cli.ts"], {
7	    input: JSON.stringify(scenario),
8	    encoding: "utf8",
9	  });
10	
11	const runCli = (scenario: unknown): string => {
12	  const { status, stdout, stderr } = runCliRaw(scenario);
13	
14	  if (status !== 0) throw new Error(`CLI exited with ${status}: ${stderr}`);
15	
16	  return stdout;
17	};
18	
19	describe("MHPCO Claim Office", () => {
20	  // --- Quote: base premiums for main items ---
21	  it("empty item list → premium 5 G (only the processing fee)", () => {
22	    const scenario = {
23	      customer: { yearsWithMHPCO: 0 },
24	      steps: [{ op: "quote", items: [] }],
25	    };

740	    expect(() => runScenario(scenario)).toThrow(/-200|negative/);
741	  });
742	
743	  // --- CLI ---
744	  it("the CLI reads a JSON scenario from stdin and writes { results } to stdout", () => {
745	    const scenario = {
746	      customer: { yearsWithMHPCO: 5 },
747	      steps: [
748	        {
749	          op: "quote",
750	          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
751	        },
752	        {
753	          op: "claim",
754	          policy: 0,
755	          incident: { cause: "fire", damages: [{ itemType: "amulet", amount: 200 }] },
756	        },
757	      ],
758	    };
759	
760	    // quote: 60 base − 12 loyalty + 6 first insurance = 54 + 5 fee = 59
761	    // claim: 200 − 100 = 100; cap 1200 − 100 = 1100 remaining
762	    expect(JSON.parse(runCli(scenario))).toEqual({
763	      results: [{ premium: 59 }, { payout: 100, remainingCap: 1100 }],
764	    });
765	  });
766	  it("the CLI exits with a non-zero status and writes to stderr on an invalid scenario, with no results on stdout", () => {
767	    const scenario = {
768	      customer: { yearsWithMHPCO: 0 },
769	      steps: [{ op: "quote", items: [{ type: "broomstick" }] }],
770	    };
771	
772	    const { status, stdout, stderr } = runCliRaw(scenario);
773	
774	    expect(status).not.toBe(0);
775	    expect(stderr).toMatch(/broomstick/);
776	    expect(stdout).toBe("");
777	  });
778	});
